//! SvelteKit docs-site emitter.
//!
//! Emits a runnable SvelteKit project split into two layers with
//! different regeneration semantics:
//!
//! - **Generated** (overwritten on every run): `src/lib/generated/docs/**`
//!   data modules plus the docs route (`src/routes/docs/[...slug]`).
//!   This is the fully-autogenerated part of the docs.
//! - **Maintained** (scaffolded once, never overwritten): the theme
//!   components (`src/lib/docs-theme/**`), root layout, landing page,
//!   app shell, and tool configs. The rest of the site is actively
//!   developed here; regeneration skips existing files.
//!
//! The contract is documented in the generated `README.md`: build the
//! site by editing the maintained layer, refresh the docs by re-running
//! `suspect docs --style sveltekit`.

use std::collections::BTreeMap;
use std::path::Path;

use super::{DocModel, escape_js, slugify};

/// What one SvelteKit render did.
#[derive(Debug, Clone, PartialEq, Eq, Default)]
pub struct SvelteKitReport {
    /// Generated-layer files written this run (overwritten).
    pub generated: Vec<String>,
    /// Maintained-layer files created this run (first scaffold).
    pub scaffolded: Vec<String>,
    /// Maintained-layer files that already existed and were left alone.
    pub skipped: Vec<String>,
}

/// Renders the SvelteKit docs site into `out_dir`.
///
/// # Errors
/// Propagates filesystem failures.
pub fn render_sveltekit(model: &DocModel, out_dir: &Path) -> std::io::Result<SvelteKitReport> {
    std::fs::create_dir_all(out_dir)?;
    let mut report = SvelteKitReport::default();

    // ------------------------------------------------ generated layer
    let slugs = Slugs::new(model);
    write_generated(
        &mut report,
        out_dir,
        "src/lib/generated/docs/toc.js",
        &toc_module(model, &slugs),
    );
    for group in &model.groups {
        let slug = &slugs.group_slugs[&group.tag];
        write_generated(
            &mut report,
            out_dir,
            &format!("src/lib/generated/docs/operations/{slug}.js"),
            &group_module(group, slug),
        );
    }
    for schema in &model.schemas {
        let slug = &slugs.schema_slugs[&schema.name];
        write_generated(
            &mut report,
            out_dir,
            &format!("src/lib/generated/docs/schemas/{slug}.js"),
            &schema_module(schema, slug),
        );
    }
    write_generated(
        &mut report,
        out_dir,
        "src/lib/generated/docs/index.js",
        &index_module(model, &slugs),
    );
    write_generated(
        &mut report,
        out_dir,
        "src/routes/docs/[...slug]/+page.js",
        LOAD_JS,
    );
    write_generated(
        &mut report,
        out_dir,
        "src/routes/docs/[...slug]/+page.svelte",
        DOCS_PAGE_SVELTE,
    );

    // ------------------------------------------------ maintained layer
    write_maintained(&mut report, out_dir, "package.json", &package_json(model));
    write_maintained(&mut report, out_dir, "svelte.config.js", SVELTE_CONFIG);
    write_maintained(&mut report, out_dir, "vite.config.js", VITE_CONFIG);
    write_maintained(&mut report, out_dir, "jsconfig.json", JSCONFIG);
    write_maintained(&mut report, out_dir, ".gitignore", GITIGNORE);
    write_maintained(&mut report, out_dir, "README.md", &readme(model));
    write_maintained(&mut report, out_dir, "src/app.html", APP_HTML);
    write_maintained(&mut report, out_dir, "src/app.css", APP_CSS);
    write_maintained(&mut report, out_dir, "src/routes/+layout.js", LAYOUT_JS);
    write_maintained(
        &mut report,
        out_dir,
        "src/routes/+layout.svelte",
        LAYOUT_SVELTE,
    );
    write_maintained(
        &mut report,
        out_dir,
        "src/routes/+page.svelte",
        LANDING_PAGE_SVELTE,
    );
    write_maintained(
        &mut report,
        out_dir,
        "src/lib/docs-theme/Sidebar.svelte",
        SIDEBAR_SVELTE,
    );
    write_maintained(
        &mut report,
        out_dir,
        "src/lib/docs-theme/Overview.svelte",
        OVERVIEW_SVELTE,
    );
    write_maintained(
        &mut report,
        out_dir,
        "src/lib/docs-theme/OperationGroup.svelte",
        OPERATION_GROUP_SVELTE,
    );
    write_maintained(
        &mut report,
        out_dir,
        "src/lib/docs-theme/SchemaView.svelte",
        SCHEMA_VIEW_SVELTE,
    );
    write_maintained(
        &mut report,
        out_dir,
        "src/lib/docs-theme/Markdown.svelte",
        MARKDOWN_SVELTE,
    );

    Ok(report)
}

/// Writes a generated-layer file, creating parent directories.
fn write_generated(report: &mut SvelteKitReport, out_dir: &Path, relative: &str, content: &str) {
    let path = out_dir.join(relative);
    if let Some(parent) = path.parent() {
        std::fs::create_dir_all(parent).expect("generated parent directory");
    }
    std::fs::write(&path, content).expect("generated file write");
    report.generated.push(relative.to_owned());
}

/// Writes a maintained-layer file only when it does not exist yet.
fn write_maintained(report: &mut SvelteKitReport, out_dir: &Path, relative: &str, content: &str) {
    let path = out_dir.join(relative);
    if path.exists() {
        report.skipped.push(relative.to_owned());
        return;
    }
    if let Some(parent) = path.parent() {
        std::fs::create_dir_all(parent).expect("maintained parent directory");
    }
    std::fs::write(&path, content).expect("maintained file write");
    report.scaffolded.push(relative.to_owned());
}

/// Slug assignments shared by the generated modules.
struct Slugs {
    /// Tag → URL/file slug (deduplicated).
    group_slugs: BTreeMap<String, String>,
    /// Schema name → URL/file slug (deduplicated).
    schema_slugs: BTreeMap<String, String>,
}

impl Slugs {
    fn new(model: &DocModel) -> Self {
        let mut issued: std::collections::BTreeSet<String> = std::collections::BTreeSet::new();
        let mut group_slugs = BTreeMap::new();
        for group in &model.groups {
            let slug = dedupe(&slugify(&group.tag), &mut issued);
            group_slugs.insert(group.tag.clone(), slug);
        }
        let mut schema_slugs = BTreeMap::new();
        for schema in &model.schemas {
            let slug = dedupe(&slugify(&schema.name), &mut issued);
            schema_slugs.insert(schema.name.clone(), slug);
        }
        Self {
            group_slugs,
            schema_slugs,
        }
    }
}

/// Deduplicates a slug against all issued ones with numeric suffixes.
fn dedupe(base: &str, issued: &mut std::collections::BTreeSet<String>) -> String {
    let mut candidate = base.to_owned();
    let mut suffix = 2;
    while issued.contains(&candidate) {
        candidate = format!("{base}-{suffix}");
        suffix += 1;
    }
    issued.insert(candidate.clone());
    candidate
}

/// A valid JS identifier for an import binding.
fn ident(text: &str) -> String {
    let mut out = String::new();
    for ch in text.chars() {
        if ch.is_ascii_alphanumeric() || ch == '_' {
            out.push(ch);
        } else {
            out.push('_');
        }
    }
    if out.chars().next().is_some_and(|c| c.is_ascii_digit()) {
        out.insert(0, '_');
    }
    if out.is_empty() {
        out.push_str("mod");
    }
    out
}

/// The `toc.js` data module: metadata plus navigation lists.
fn toc_module(model: &DocModel, slugs: &Slugs) -> String {
    let groups: Vec<String> = model
        .groups
        .iter()
        .map(|group| {
            let slug = &slugs.group_slugs[&group.tag];
            format!(
                "\t{{ tag: '{}', slug: '{}', href: '/docs/operations/{}', count: {} }},",
                escape_js(&group.tag),
                escape_js(slug),
                escape_js(slug),
                group.operations.len()
            )
        })
        .collect();
    let schemas: Vec<String> = model
        .schemas
        .iter()
        .map(|schema| {
            let slug = &slugs.schema_slugs[&schema.name];
            format!(
                "\t{{ name: '{}', slug: '{}', href: '/docs/schemas/{}' }},",
                escape_js(&schema.name),
                escape_js(slug),
                escape_js(slug)
            )
        })
        .collect();
    let description = model.description.clone().unwrap_or_default();
    format!(
        "// GENERATED by suspect docs — overwritten on every regeneration.\n\
         // The maintained layer lives in src/lib/docs-theme and src/routes.\n\n\
         export const meta = {{\n\ttitle: '{}',\n\tversion: '{}',\n\tdescription: '{}',\n\t\
         servers: [{}],\n}};\n\n\
         export const groups = [\n{}\n];\n\n\
         export const schemas = [\n{}\n];\n",
        escape_js(&model.title),
        escape_js(&model.version),
        escape_js(&description),
        model
            .servers
            .iter()
            .map(|s| format!("'{}'", escape_js(s)))
            .collect::<Vec<_>>()
            .join(", "),
        groups.join("\n"),
        schemas.join("\n"),
    )
}

/// One operation-group data module.
fn group_module(group: &super::OpGroup, slug: &str) -> String {
    let operations: Vec<serde_json::Value> = group
        .operations
        .iter()
        .map(|op| {
            serde_json::json!({
                "method": op.method,
                "path": op.path,
                "operationId": op.operation_id,
                "summary": op.summary,
                "description": op.description,
                "deprecated": op.deprecated,
                "parameters": op.parameters.iter().map(|p| serde_json::json!({
                    "name": p.name,
                    "in": p.location,
                    "required": p.required,
                    "type": p.type_desc,
                    "description": p.description,
                })).collect::<Vec<_>>(),
                "requestBody": op.request_body.as_ref().map(|b| serde_json::json!({
                    "contentType": b.content_type,
                    "type": b.type_desc,
                    "required": b.required,
                })),
                "responses": op.responses.iter().map(|r| serde_json::json!({
                    "status": r.status,
                    "description": r.description,
                    "contentType": r.content_type,
                    "type": r.type_desc,
                })).collect::<Vec<_>>(),
            })
        })
        .collect();
    let body = serde_json::to_string_pretty(&operations).unwrap_or_else(|_| "[]".to_owned());
    format!(
        "// GENERATED by suspect docs — overwritten on every regeneration.\n\n\
         export const tag = '{}';\n\
         export const slug = '{}';\n\
         export const operations = {};\n",
        escape_js(&group.tag),
        escape_js(slug),
        body
    )
}

/// One schema data module.
fn schema_module(schema: &super::SchemaDoc, slug: &str) -> String {
    let value = serde_json::json!({
        "name": schema.name,
        "slug": slug,
        "description": schema.description,
        "properties": schema.properties.iter().map(|p| serde_json::json!({
            "name": p.name,
            "type": p.type_desc,
            "required": p.required,
            "description": p.description,
        })).collect::<Vec<_>>(),
    });
    let body = serde_json::to_string_pretty(&value).unwrap_or_else(|_| "{}".to_owned());
    format!(
        "// GENERATED by suspect docs — overwritten on every regeneration.\n\n\
         export const schema = {body};\n"
    )
}

/// The aggregate module mapping slugs to the data modules.
fn index_module(model: &DocModel, slugs: &Slugs) -> String {
    let mut out =
        String::from("// GENERATED by suspect docs — overwritten on every regeneration.\n\n");
    let mut operation_entries = Vec::new();
    for group in &model.groups {
        let slug = &slugs.group_slugs[&group.tag];
        let binding = format!("op_{}", ident(slug));
        out.push_str(&format!(
            "import * as {binding} from './operations/{slug}.js';\n"
        ));
        operation_entries.push(format!("\t'{}': {binding},", escape_js(slug)));
    }
    let mut schema_entries = Vec::new();
    for schema in &model.schemas {
        let slug = &slugs.schema_slugs[&schema.name];
        let binding = format!("schema_{}", ident(slug));
        out.push_str(&format!(
            "import * as {binding} from './schemas/{slug}.js';\n"
        ));
        schema_entries.push(format!("\t'{}': {binding},", escape_js(slug)));
    }
    out.push_str("\nexport const operationModules = {\n");
    out.push_str(&operation_entries.join("\n"));
    out.push_str("\n};\n\nexport const schemaModules = {\n");
    out.push_str(&schema_entries.join("\n"));
    out.push_str("\n};\n");
    let _ = model;
    out
}

// ---------------------------------------------------------------- templates

const LOAD_JS: &str = r"// GENERATED by suspect docs — overwritten on every regeneration.
import { error } from '@sveltejs/kit';
import { operationModules, schemaModules } from '$lib/generated/docs/index.js';
import { meta, groups, schemas } from '$lib/generated/docs/toc.js';

const navigation = { meta, groups, schemas };

/** @type {import('./$types').PageLoad} */
export function load({ params }) {
  // `/docs` lands here with an empty rest param.
  const slug = params.slug || 'overview';
  if (slug === 'overview') {
    return { overview: true, navigation, slug };
  }
  if (slug.startsWith('operations/')) {
    const mod = operationModules[slug.slice('operations/'.length)];
    if (!mod) error(404, 'Docs page not found');
    return {
      group: { tag: mod.tag, slug: mod.slug, operations: mod.operations },
      navigation,
      slug
    };
  }
  if (slug.startsWith('schemas/')) {
    const mod = schemaModules[slug.slice('schemas/'.length)];
    if (!mod) error(404, 'Docs page not found');
    return { schema: mod.schema, navigation, slug };
  }
  error(404, 'Docs page not found');
}
";

