#[cfg(test)]
mod tests {
    use super::super::{extract, fixture};
    use super::*;

    #[test]
    fn scaffolds_then_regen_updates_only_generated_layer() {
        let model = extract(&fixture::sample());
        let dir = tempfile::tempdir().unwrap();
        let out = dir.path().join("site");

        // First run: everything scaffolded.
        let first = render_sveltekit(&model, &out).unwrap();
        assert!(first.skipped.is_empty());
        assert!(
            first
                .scaffolded
                .contains(&"src/lib/docs-theme/Sidebar.svelte".to_owned())
        );
        assert!(
            first
                .generated
                .contains(&"src/lib/generated/docs/index.js".to_owned())
        );
        assert!(
            first
                .generated
                .contains(&"src/routes/docs/[...slug]/+page.js".to_owned())
        );
        let scaffolded_count = first.scaffolded.len();
        assert!(scaffolded_count >= 15, "full scaffold: {scaffolded_count}");

        // A maintainer personalizes the theme and adds a route.
        let sidebar = out.join("src/lib/docs-theme/Sidebar.svelte");
        let personalized = std::fs::read_to_string(&sidebar).unwrap() + "\n<!-- mine -->";
        std::fs::write(&sidebar, &personalized).unwrap();
        let extra = out.join("src/routes/about/+page.svelte");
        std::fs::create_dir_all(extra.parent().unwrap()).unwrap();
        std::fs::write(&extra, "<h1>About</h1>").unwrap();

        // Second run: generated layer refreshed, maintained layer intact.
        let second = render_sveltekit(&model, &out).unwrap();
        assert!(second.scaffolded.is_empty());
        assert_eq!(second.skipped.len(), scaffolded_count);
        assert!(
            second
                .generated
                .contains(&"src/lib/generated/docs/operations/pets.js".to_owned())
        );
        assert_eq!(
            std::fs::read_to_string(&sidebar).unwrap(),
            personalized,
            "maintained theme must survive regeneration"
        );
        assert_eq!(
            std::fs::read_to_string(&extra).unwrap(),
            "<h1>About</h1>",
            "maintained routes must survive regeneration"
        );
    }

    #[test]
    fn generated_data_modules_carry_the_model() {
        let model = extract(&fixture::sample());
        let dir = tempfile::tempdir().unwrap();
        let out = dir.path().join("site");
        render_sveltekit(&model, &out).unwrap();

        let index = std::fs::read_to_string(out.join("src/lib/generated/docs/index.js")).unwrap();
        assert!(index.contains("import * as op_pets from './operations/pets.js';"));
        assert!(index.contains("import * as schema_pet from './schemas/pet.js';"));
        assert!(index.contains("'pets': op_pets,"));
        assert!(index.contains("'pet': schema_pet,"));

        let toc = std::fs::read_to_string(out.join("src/lib/generated/docs/toc.js")).unwrap();
        assert!(toc.contains("title: 'Test API'"));
        assert!(toc.contains("href: '/docs/operations/pets', count: 2"));
        assert!(toc.contains("href: '/docs/schemas/pet'"));

        let pets =
            std::fs::read_to_string(out.join("src/lib/generated/docs/operations/pets.js")).unwrap();
        assert!(pets.contains("\"method\": \"GET\""));
        assert!(pets.contains("\"operationId\": \"listPets\""));
        assert!(pets.contains("\"type\": \"Pet\""));

        let load = std::fs::read_to_string(out.join("src/routes/docs/[...slug]/+page.js")).unwrap();
        assert!(load.contains("operationModules[slug.slice('operations/'.length)]"));
        assert!(load.contains("error(404, 'Docs page not found')"));

        // Route slugs are deduplicated across groups and schemas.
        let pet =
            std::fs::read_to_string(out.join("src/lib/generated/docs/schemas/pet.js")).unwrap();
        assert!(pet.contains("export const schema = {"));
        assert!(pet.contains("\"required\": true"));
    }

    #[test]
    fn slugs_deduplicate_across_kinds() {
        let mut issued = std::collections::BTreeSet::new();
        assert_eq!(dedupe("pets", &mut issued), "pets");
        assert_eq!(dedupe("pets", &mut issued), "pets-2");
        assert_eq!(dedupe("pets", &mut issued), "pets-3");
    }

    #[test]
    fn package_json_is_valid_json_and_readme_documents_the_contract() {
        let model = extract(&fixture::sample());
        let dir = tempfile::tempdir().unwrap();
        let out = dir.path().join("site");
        render_sveltekit(&model, &out).unwrap();

        let package = std::fs::read_to_string(out.join("package.json")).unwrap();
        let json: serde_json::Value = serde_json::from_str(&package).unwrap();
        assert_eq!(json["name"], "test-api-docs");
        assert_eq!(json["scripts"]["build"], "vite build");

        let readme = std::fs::read_to_string(out.join("README.md")).unwrap();
        assert!(readme.contains("**Overwritten every run**"));
        assert!(readme.contains("src/lib/generated/"));
        assert!(readme.contains("suspect docs <openapi.yaml> --style sveltekit --out ."));
    }
}
